class Solution:
    def maximumBooks(self, books: list[int]) -> int:
        n = len(books)
        stk = []
        dp = [0] * n
        for i in range(n):
            while stk and books[stk[-1]] - stk[-1] >= books[i] - i:
                stk.pop()
            j = stk[-1] if stk else -1
            cnt = min(books[i], i - j)
            first_val = books[i] - cnt + 1
            sum_books = cnt * (first_val + books[i]) // 2
            dp[i] = (dp[j] if j != -1 else 0) + sum_books
            stk.append(i)
        return max(dp)

class Solution {
public:
    long long maximumBooks(std::vector<int>& books) {
        int n = books.size();
        std::vector<int> stk;
        std::vector<long long> dp(n, 0);
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            while (!stk.empty() && books[stk.back()] - stk.back() >= books[i] - i) {
                stk.pop_back();
            }
            int j = stk.empty() ? -1 : stk.back();
            long long cnt = std::min((long long)books[i], (long long)(i - j));
            long long first_val = books[i] - cnt + 1;
            long long sum_books = cnt * (first_val + books[i]) / 2;
            dp[i] = (j != -1 ? dp[j] : 0) + sum_books;
            stk.push_back(i);
            ans = std::max(ans, dp[i]);
        }
        return ans;
    }
};

class Solution {
    public long maximumBooks(int[] books) {
        int n = books.length;
        int[] stk = new int[n];
        int top = -1;
        long[] dp = new long[n];
        long ans = 0;
        for (int i = 0; i < n; ++i) {
            while (top >= 0 && books[stk[top]] - stk[top] >= books[i] - i) {
                top--;
            }
            int j = top >= 0 ? stk[top] : -1;
            long cnt = Math.min((long) books[i], (long) (i - j));
            long firstVal = books[i] - cnt + 1;
            long sumBooks = cnt * (firstVal + books[i]) / 2;
            dp[i] = (j != -1 ? dp[j] : 0) + sumBooks;
            stk[++top] = i;
            ans = Math.max(ans, dp[i]);
        }
        return ans;
    }
}

var maximumBooks = function(books) {
    const n = books.length;
    const stk = [];
    const dp = new Array(n).fill(0n);
    let ans = 0n;
    for (let i = 0; i < n; ++i) {
        while (stk.length && BigInt(books[stk[stk.length - 1]] - stk[stk.length - 1]) >= BigInt(books[i] - i)) {
            stk.pop();
        }
        const j = stk.length ? stk[stk.length - 1] : -1;
        const bVal = BigInt(books[i]);
        const span = BigInt(i - j);
        const cnt = bVal < span ? bVal : span;
        const firstVal = bVal - cnt + 1n;
        const sumBooks = cnt * (firstVal + bVal) / 2n;
        dp[i] = (j !== -1 ? dp[j] : 0n) + sumBooks;
        stk.push(i);
        if (dp[i] > ans) ans = dp[i];
    }
    return Number(ans);
};
